const PLATFORM_SETTINGS_PERSISTENCE_FAILED: &str = "PLATFORM_SETTINGS_PERSISTENCE_FAILED";
const PLATFORM_SETTINGS_READ_FAILED: &str = "PLATFORM_SETTINGS_READ_FAILED";

fn platform_settings_persistence_problem() -> ProblemDetails {
    problem_details(
        StatusCode::INTERNAL_SERVER_ERROR,
        PLATFORM_SETTINGS_PERSISTENCE_FAILED,
        "Platform settings could not be persisted",
        None::<&str>,
    )
}

fn map_platform_settings_persistence_result<T, E: std::fmt::Display>(
    result: Result<T, E>,
    backend: &str,
    key: Option<&str>,
) -> Result<T, ProblemDetails> {
    result.map_err(|error| {
        tracing::error!(
            backend,
            key = ?key,
            error = %error,
            "platform settings persistence failed"
        );
        platform_settings_persistence_problem()
    })
}

fn platform_settings_read_problem() -> ProblemDetails {
    problem_details(
        StatusCode::INTERNAL_SERVER_ERROR,
        PLATFORM_SETTINGS_READ_FAILED,
        "Platform settings could not be loaded",
        None::<&str>,
    )
}

fn map_platform_settings_read_result<T, E: std::fmt::Display>(
    result: Result<T, E>,
    backend: &str,
) -> Result<T, ProblemDetails> {
    result.map_err(|error| {
        tracing::error!(
            backend,
            error = %error,
            "platform settings read failed"
        );
        platform_settings_read_problem()
    })
}

async fn upsert_platform_config_entries(
    pool: &sqlx::PgPool,
    config: &PlatformConfig,
) -> Result<(), ProblemDetails> {
    let entries = platform_config_entries(config);
    for (key, value) in &entries {
        map_platform_settings_persistence_result(
            sqlx::query(
                "INSERT INTO platform_config (key, value, updated_at) VALUES ($1, $2, NOW()) \
                 ON CONFLICT (key) DO UPDATE SET value = $2, updated_at = NOW()",
            )
            .bind(key)
            .bind(value)
            .execute(pool)
            .await,
            "database",
            Some(key),
        )?;
    }
    Ok(())
}

async fn save_platform_config_file(config: &PlatformConfig) -> Result<(), ProblemDetails> {
    map_platform_settings_persistence_result(
        crate::config_store::save_config(config).await,
        "file",
        None,
    )
}

async fn admin_platform_settings(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    require_admin_permission(&session)?;

    if let Some(pool) = get_db() {
        let rows: Vec<(String, String)> = map_platform_settings_read_result(
            sqlx::query_as("SELECT key, value FROM platform_config")
                .fetch_all(pool)
                .await,
            "database",
        )?;
        let mut config = PlatformConfig::default();
        for (key, value) in &rows {
            apply_platform_config_entry(&mut config, key, value);
        }
        return Ok(Json(serde_json::to_value(config).unwrap_or_default()));
    }
    let config =
        map_platform_settings_read_result(crate::config_store::load_config().await, "file")?;
    Ok(Json(serde_json::to_value(config).unwrap_or_default()))
}

async fn admin_platform_settings_update(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<PlatformConfig>,
) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    require_verified_external_admin_permission(
        &session,
        &crate::config_store::get_app_config().auth_mode,
    )?;

    let validation_errors = ryuki_core::types::validate_platform_config(&body);
    if !validation_errors.is_empty() {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(ApiError::with_detail(
                "CONFIG_VALIDATION_FAILED",
                "Platform configuration validation failed",
                validation_errors.join("; "),
            )),
        ));
    }

    if let Some(pool) = get_db() {
        upsert_platform_config_entries(pool, &body).await?;
    }
    save_platform_config_file(&body).await?;
    let config = if get_db().is_some() {
        body
    } else {
        map_platform_settings_read_result(crate::config_store::load_config().await, "file")?
    };
    Ok(Json(serde_json::to_value(config).unwrap_or_default()))
}

async fn admin_platform_settings_reset(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    require_verified_external_admin_permission(
        &session,
        &crate::config_store::get_app_config().auth_mode,
    )?;

    let defaults = PlatformConfig::default();
    if let Some(pool) = get_db() {
        upsert_platform_config_entries(pool, &defaults).await?;
    }
    save_platform_config_file(&defaults).await?;
    Ok(Json(serde_json::to_value(defaults).unwrap_or_default()))
}

// ─── API token & session administration handlers (design doc feature 3) ───

/// base64url-no-pad alphabet (`[A-Za-z0-9_-]`) used to encode the 32 raw CSPRNG
/// bytes. Chosen over standard base64 so the token is header/URL-safe (no `+`,
/// `/`, or `=`) and copy-paste clean.
fn generate_api_token() -> String {
    use rand::rngs::OsRng;
    use rand::RngCore;
    let mut raw = [0u8; 32];
    OsRng.fill_bytes(&mut raw);
    let encoded = base64::Engine::encode(&base64::engine::general_purpose::URL_SAFE_NO_PAD, raw);
    format!("{}{}", crate::API_TOKEN_PREFIX, encoded)
}

#[derive(Debug, Deserialize)]
struct CreateTokenRequest {
    name: String,
    owner_principal: String,
    #[serde(default)]
    roles: Vec<String>,
    #[serde(default)]
    site_scope: Option<String>,
    #[serde(default)]
    environment_scope: Option<String>,
    #[serde(default)]
    expires_at: Option<String>,
}

/// Returns the first requested role that is not in the application role catalog.
fn find_unknown_role(roles: &[String]) -> Option<&str> {
    roles
        .iter()
        .map(String::as_str)
        .find(|role| !ryuki_engine::auth::ALL_APP_ROLES.contains(role))
}

/// Persistence failure for the api_tokens table. The raw DB error is logged but
/// never returned to the caller.
fn api_token_persistence_problem() -> (StatusCode, Json<ApiError>) {
    (
        StatusCode::INTERNAL_SERVER_ERROR,
        Json(ApiError::new(
            "API_TOKEN_PERSISTENCE_FAILED",
            "API token could not be persisted",
        )),
    )
}

fn map_api_token_result<T, E: std::fmt::Display>(
    result: Result<T, E>,
    operation: &str,
) -> Result<T, (StatusCode, Json<ApiError>)> {
    result.map_err(|error| {
        tracing::error!(operation, error = %error, "api token persistence failed");
        api_token_persistence_problem()
    })
}

fn api_token_db_required() -> (StatusCode, Json<ApiError>) {
    (
        StatusCode::SERVICE_UNAVAILABLE,
        Json(ApiError::new(
            "DATABASE_REQUIRED",
            "API token administration requires a database",
        )),
    )
}

/// Row returned to list callers — `token_hash` is REDACTED (never serialized).
#[derive(sqlx::FromRow)]
struct TokenListRow {
    id: Uuid,
    name: String,
    owner_principal: String,
    roles: Vec<String>,
    site_scope: Option<String>,
    environment_scope: Option<String>,
    token_valid: bool,
    created_at: chrono::DateTime<chrono::Utc>,
    expires_at: Option<chrono::DateTime<chrono::Utc>>,
    last_used_at: Option<chrono::DateTime<chrono::Utc>>,
    revoked_at: Option<chrono::DateTime<chrono::Utc>>,
}

/// POST /api/admin/tokens — mint a service-account credential. The plaintext
/// `ryk_...` token is returned EXACTLY ONCE in this response and is never
/// persisted (only its SHA-256 hash) or logged.
async fn admin_tokens_create(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<CreateTokenRequest>,
) -> Result<(StatusCode, Json<Value>), (StatusCode, Json<ApiError>)> {
    require_admin_permission(&session)?;

    // Only an interactive admin may mint tokens. A machine `api-token` passing
    // the admin gate must not be able to mint further admin tokens — that would
    // be a self-perpetuating credential chain with no interactive re-auth ever
    // re-entering the loop. Token issuance is an interactive administrative act.
    if session.provider_mode == "api-token" {
        return Err((
            StatusCode::FORBIDDEN,
            Json(ApiError::new(
                "INTERACTIVE_ADMIN_REQUIRED",
                "API tokens cannot mint other tokens; sign in interactively to issue tokens",
            )),
        ));
    }

    if let Some(unknown) = find_unknown_role(&body.roles) {
        return Err((
            StatusCode::BAD_REQUEST,
            Json(ApiError::with_detail(
                "UNKNOWN_ROLE",
                "Requested role is not a known application role",
                unknown.to_string(),
            )),
        ));
    }

    // Parse the optional RFC3339 expiry. A malformed value is a 400, never a
    // silently-ignored "never expires".
    let expires_at: Option<chrono::DateTime<chrono::Utc>> = match &body.expires_at {
        Some(raw) => Some(
            chrono::DateTime::parse_from_rfc3339(raw)
                .map_err(|_| {
                    (
                        StatusCode::BAD_REQUEST,
                        Json(ApiError::new(
                            "INVALID_EXPIRES_AT",
                            "expires_at must be an RFC3339 timestamp",
                        )),
                    )
                })?
                .with_timezone(&chrono::Utc),
        ),
        None => None,
    };

    let Some(pool) = get_db() else {
        return Err(api_token_db_required());
    };

    // Dry-run-non-privileged safety rule made durable: tokens minted while the
    // auth mode is a dry-run mode are token_valid=FALSE forever, so they can
    // never satisfy require_verified_external_admin_permission even after the
    // mode later changes. Only an EntraId/Local mint by a token_valid session
    // is TRUE.
    let auth_mode = crate::config_store::get_app_config().auth_mode.clone();
    let token_valid =
        matches!(auth_mode, AuthMode::EntraId | AuthMode::Local) && session.token_valid;

    // Plaintext exists only transiently here and in the 201 response below; it
    // is hashed for storage and never written to a column or a log.
    let plaintext = generate_api_token();
    let token_hash = crate::sha256_hex(&plaintext);

    let row: TokenListRow = map_api_token_result(
        sqlx::query_as::<_, TokenListRow>(
            "INSERT INTO api_tokens \
             (name, owner_principal, token_hash, roles, site_scope, environment_scope, token_valid, expires_at) \
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8) \
             RETURNING id, name, owner_principal, roles, site_scope, environment_scope, \
                       token_valid, created_at, expires_at, last_used_at, revoked_at",
        )
        .bind(&body.name)
        .bind(&body.owner_principal)
        .bind(&token_hash)
        .bind(&body.roles)
        .bind(&body.site_scope)
        .bind(&body.environment_scope)
        .bind(token_valid)
        .bind(expires_at)
        .fetch_one(pool)
        .await,
        "create",
    )?;

    // Audit line: actor + action + token metadata. NEVER the plaintext or hash.
    tracing::info!(
        actor = %session.user_id,
        action = "api-token-create",
        token_id = %row.id,
        token_name = %row.name,
        owner_principal = %row.owner_principal,
        roles = ?row.roles,
        site_scope = ?row.site_scope,
        environment_scope = ?row.environment_scope,
        token_valid = row.token_valid,
        "api token created"
    );

    Ok((
        StatusCode::CREATED,
        Json(json!({
            "id": row.id,
            "name": row.name,
            "owner_principal": row.owner_principal,
            "roles": row.roles,
            "site_scope": row.site_scope,
            "environment_scope": row.environment_scope,
            "token_valid": row.token_valid,
            "expires_at": row.expires_at,
            "created_at": row.created_at,
            // ONE-TIME plaintext reveal — never returned again, never stored.
            "token": plaintext,
        })),
    ))
}

/// GET /api/admin/tokens — list token metadata with the hash REDACTED. Reads
/// are not gated by the central ROUTE_PERMISSIONS table this wave, so the
/// handler enforces the admin gate explicitly (these reads expose token
/// metadata).
async fn admin_tokens_list(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    require_admin_permission(&session)?;

    let Some(pool) = get_db() else {
        return Err(api_token_db_required());
    };

    let rows: Vec<TokenListRow> = map_api_token_result(
        sqlx::query_as::<_, TokenListRow>(
            "SELECT id, name, owner_principal, roles, site_scope, environment_scope, \
                    token_valid, created_at, expires_at, last_used_at, revoked_at \
             FROM api_tokens ORDER BY created_at DESC",
        )
        .fetch_all(pool)
        .await,
        "list",
    )?;

    let tokens: Vec<Value> = rows
        .into_iter()
        .map(|row| {
            json!({
                "id": row.id,
                "name": row.name,
                "owner_principal": row.owner_principal,
                "roles": row.roles,
                "site_scope": row.site_scope,
                "environment_scope": row.environment_scope,
                "token_valid": row.token_valid,
                "created_at": row.created_at,
                "expires_at": row.expires_at,
                "last_used_at": row.last_used_at,
                "revoked_at": row.revoked_at,
                // Hash is never exposed; plaintext is unrecoverable by design.
                "token_hash": Value::Null,
            })
        })
        .collect();

    Ok(Json(json!({ "tokens": tokens })))
}

/// DELETE /api/admin/tokens/{id} — soft-revoke (sets revoked_at). 404 when no
/// active token by that id (already-revoked or absent are indistinguishable to
/// the caller). Never a hard DELETE: the row survives as evidence.
async fn admin_tokens_revoke(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<Uuid>,
) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    require_admin_permission(&session)?;

    let Some(pool) = get_db() else {
        return Err(api_token_db_required());
    };

    let result = map_api_token_result(
        sqlx::query(
            "UPDATE api_tokens SET revoked_at = NOW() WHERE id = $1 AND revoked_at IS NULL",
        )
        .bind(id)
        .execute(pool)
        .await,
        "revoke",
    )?;

    if result.rows_affected() == 0 {
        return Err((
            StatusCode::NOT_FOUND,
            Json(ApiError::new(
                "NOT_FOUND",
                "No active API token with that id",
            )),
        ));
    }

    tracing::info!(
        actor = %session.user_id,
        action = "api-token-revoke",
        token_id = %id,
        "api token revoked"
    );

    Ok(Json(json!({ "status": "revoked", "id": id })))
}

#[derive(sqlx::FromRow)]
struct SessionListRow {
    id: Uuid,
    user_id: String,
    display_name: String,
    roles: Vec<String>,
    provider: String,
    created_at: chrono::DateTime<chrono::Utc>,
    expires_at: chrono::DateTime<chrono::Utc>,
}

/// GET /api/admin/sessions — list active (non-expired) browser sessions.
async fn admin_sessions_list(
    AuthExtractor(session): AuthExtractor,
) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    require_admin_permission(&session)?;

    let Some(pool) = get_db() else {
        return Err(api_token_db_required());
    };

    let rows: Vec<SessionListRow> = map_api_token_result(
        sqlx::query_as::<_, SessionListRow>(
            "SELECT id, user_id, display_name, roles, provider, created_at, expires_at \
             FROM sessions WHERE expires_at > NOW() ORDER BY created_at DESC",
        )
        .fetch_all(pool)
        .await,
        "list-sessions",
    )?;

    let sessions: Vec<Value> = rows
        .into_iter()
        .map(|row| {
            json!({
                "id": row.id,
                "user_id": row.user_id,
                "display_name": row.display_name,
                "roles": row.roles,
                "provider": row.provider,
                "created_at": row.created_at,
                "expires_at": row.expires_at,
            })
        })
        .collect();

    Ok(Json(json!({ "sessions": sessions })))
}

/// DELETE /api/admin/sessions/{id} — admin revoke of ANY session (closes the
/// self-only gap in auth_logout). Sessions are ephemeral, so a hard DELETE is
/// acceptable here (unlike tokens, which are soft-revoked as evidence). 404
/// when absent.
async fn admin_sessions_revoke(
    AuthExtractor(session): AuthExtractor,
    Path(id): Path<Uuid>,
) -> Result<Json<Value>, (StatusCode, Json<ApiError>)> {
    require_admin_permission(&session)?;

    let Some(pool) = get_db() else {
        return Err(api_token_db_required());
    };

    let result = map_api_token_result(
        sqlx::query("DELETE FROM sessions WHERE id = $1")
            .bind(id)
            .execute(pool)
            .await,
        "revoke-session",
    )?;

    if result.rows_affected() == 0 {
        return Err((
            StatusCode::NOT_FOUND,
            Json(ApiError::new("NOT_FOUND", "No session with that id")),
        ));
    }

    tracing::info!(
        actor = %session.user_id,
        action = "session-revoke",
        session_id = %id,
        "session revoked by admin"
    );

    Ok(Json(json!({ "status": "revoked", "id": id })))
}

// ─── Request lifecycle handlers ───

/// Custom extractor: pulls AuthSession from request extensions injected by auth middleware.
struct AuthExtractor(AuthSession);

fn auth_session_is_verified_or_static(session: &AuthSession) -> bool {
    session.token_valid || session.provider_mode == "static-dry-run"
}

impl<S: Send + Sync> axum::extract::FromRequestParts<S> for AuthExtractor {
    type Rejection = (StatusCode, Json<serde_json::Value>);

    async fn from_request_parts(
        parts: &mut axum::http::request::Parts,
        _state: &S,
    ) -> Result<Self, Self::Rejection> {
        let session = parts
            .extensions
            .get::<AuthSession>()
            .cloned()
            .ok_or_else(|| {
                (
                    StatusCode::UNAUTHORIZED,
                    Json(json!({"error": "No session found"})),
                )
            })?;

        if !auth_session_is_verified_or_static(&session) {
            return Err((
                StatusCode::UNAUTHORIZED,
                Json(json!({"error": "Auth token is not verified"})),
            ));
        }

        Ok(AuthExtractor(session))
    }
}

type ApiResult = Result<Json<Value>, (StatusCode, Json<Value>)>;

fn status_400(msg: &str) -> (StatusCode, Json<Value>) {
    (StatusCode::BAD_REQUEST, Json(json!({"error": msg})))
}

fn status_404(id: &str) -> (StatusCode, Json<Value>) {
    (
        StatusCode::NOT_FOUND,
        Json(json!({"error": format!("Request {id} not found")})),
    )
}

fn status_403() -> (StatusCode, Json<Value>) {
    (
        StatusCode::FORBIDDEN,
        Json(json!({"error": "Admin role required for approval"})),
    )
}

fn status_409(msg: &str) -> (StatusCode, Json<Value>) {
    (StatusCode::CONFLICT, Json(json!({"error": msg})))
}

/// 409 for a LOST compare-and-set in `apply_transition_audited`: the request
/// row's status changed between the unguarded pre-read (which the pure engine
/// guard ran against) and the conditional UPDATE, so a concurrent identical
/// transition already landed. This is a transient-conflict signal distinct from
/// the engine's 400 invalid-transition: reload and retry.
fn transition_conflict_409(request_id: &str) -> (StatusCode, Json<Value>) {
    (
        StatusCode::CONFLICT,
        Json(json!({
            "error": "Request was modified concurrently; reload and retry",
            "request_id": request_id,
        })),
    )
}

/// Maps any database/transaction error to a 500. Used by the transactional
/// lifecycle handlers where the request UPDATE and the audit INSERT commit
/// together.
fn db_error<E: std::fmt::Display>(e: E) -> (StatusCode, Json<Value>) {
    (
        StatusCode::INTERNAL_SERVER_ERROR,
        Json(json!({"error": e.to_string()})),
    )
}

/// Applies a lifecycle transition to a request row AND records its audit entry
/// in ONE transaction, so a row can never transition without its audit trail
/// (and vice versa). `current` is the pre-transition row (supplies the
/// from_status/from_stage attribution); `to_status`/`to_stage` are the
/// post-transition DB values; actor identity is taken from `session`.
///
/// CONCURRENCY (B2): the request UPDATE is a compare-and-set conditioned on
/// `expected_from_status` (the row's CURRENT status that the pure engine guard
/// just accepted, captured from each handler's unguarded pre-read). The CAS
/// `WHERE id = $3 AND status = $4` guarantees the UPDATE only lands if the row
/// is STILL in exactly that status, so N concurrent identical transitions
/// produce exactly ONE row update + ONE audit row; the losers match zero rows
/// and roll back to a 409. This makes the read-guard-write effectively
/// serializable without a separate `SELECT ... FOR UPDATE` — the atomic
/// conditional UPDATE is the lock.
/// Artifacts a transition produces that must be persisted DURABLY alongside the
/// status/stage flip, so a restart preserves the full lifecycle (P2) — not just
/// status/stage. Each is threaded into the CAS UPDATE: `stages` is always
/// overwritten with the latest cumulative Vec<Stage>; `plan`/`validation`/
/// `approval_route` use COALESCE so a transition that does not produce one
/// leaves the prior value intact.
struct TransitionArtifacts {
    /// serde of the engine-produced Vec<Stage> for this transition (always Some
    /// in practice; the engine returns the cumulative stages each step).
    stages_json: Value,
    /// Some for plan, None otherwise.
    plan_json: Option<Value>,
    /// Some for validate, None otherwise.
    validation_json: Option<Value>,
    /// Some for approve, None otherwise.
    approval_route_json: Option<Value>,
    /// Approval-decision ledger row: the route role this decision satisfies and
    /// 'approved'/'rejected'. Both Some only for approve/reject; the reject
    /// reason rides in `approval_reason`.
    approval_role: Option<String>,
    approval_decision: Option<&'static str>,
    approval_reason: Option<String>,
}

impl TransitionArtifacts {
    /// A transition that produces only the cumulative stage history (lock,
    /// execute, verify, cancel): stages persist, everything else is left intact.
    fn stages_only(stages_json: Value) -> Self {
        TransitionArtifacts {
            stages_json,
            plan_json: None,
            validation_json: None,
            approval_route_json: None,
            approval_role: None,
            approval_decision: None,
            approval_reason: None,
        }
    }
}

/// Persists a lifecycle transition atomically: the CAS `UPDATE requests` (which
/// now also writes the durable stages/plan/validation/approval_route blobs),
/// the `audit_log` insert, and — for approve/reject — the
/// `request_approval_decisions` row all commit in ONE transaction. A row can
/// never transition without its audit entry, and can never be approved/rejected
/// without its decision row.
#[allow(clippy::too_many_arguments)]
async fn apply_transition_audited(
    pool: &sqlx::PgPool,
    session: &AuthSession,
    uid: Uuid,
    current: &DbRequestRow,
    action: &str,
    expected_from_status: &str,
    to_status: &str,
    to_stage: &str,
    detail: Value,
    artifacts: TransitionArtifacts,
) -> Result<DbRequestRow, (StatusCode, Json<Value>)> {
    let mut tx = pool.begin().await.map_err(db_error)?;

    // The CAS condition `AND status = $9` is unchanged so the concurrency/409
    // invariant holds. `stages` is always overwritten with the latest full
    // Vec<Stage>; plan/validation_results/approval_route use COALESCE so a
    // transition that does not produce one leaves the prior value intact.
    let update_sql = format!(
        "UPDATE requests SET status = $1, stage = $2, stages = $3::jsonb, \
         plan = COALESCE($4::jsonb, plan), \
         validation_results = COALESCE($5::jsonb, validation_results), \
         approval_route = COALESCE($6::jsonb, approval_route), \
         updated_at = NOW() WHERE id = $7 AND status = $8 RETURNING {REQUEST_COLUMNS}"
    );
    let maybe_row: Option<DbRequestRow> = sqlx::query_as(&update_sql)
        .bind(to_status)
        .bind(to_stage)
        .bind(&artifacts.stages_json)
        .bind(&artifacts.plan_json)
        .bind(&artifacts.validation_json)
        .bind(&artifacts.approval_route_json)
        .bind(uid)
        .bind(expected_from_status)
        .fetch_optional(&mut *tx)
        .await
        .map_err(db_error)?;

    let request_id = uid.to_string();

    let Some(row) = maybe_row else {
        // Zero rows updated: the status changed under us (a concurrent
        // identical transition already applied) or the row vanished. Roll back
        // and signal a transient 409 — distinct from the engine's 400.
        tx.rollback().await.ok();
        return Err(transition_conflict_409(&request_id));
    };

    audit::record_audit_tx(
        &mut tx,
        session,
        &AuditRecord {
            action,
            request_id: Some(&request_id),
            from_status: Some(&current.status),
            to_status: &row.status,
            from_stage: Some(&current.stage),
            to_stage: &row.stage,
            detail,
            outcome: "applied",
        },
    )
    .await
    .map_err(db_error)?;

    // Approval ledger: when this transition is an approve/reject, persist the
    // decision row in the SAME tx as the status flip. ON CONFLICT makes a
    // re-approve after the CAS idempotent (it never aborts the tx on the
    // UNIQUE). The no-DB path does NOT touch this table.
    if let (Some(role), Some(decision)) = (
        artifacts.approval_role.as_deref(),
        artifacts.approval_decision,
    ) {
        sqlx::query(
            "INSERT INTO request_approval_decisions (request_id, role, decision, actor, reason) \
             VALUES ($1, $2, $3, $4, $5) \
             ON CONFLICT (request_id, role) \
             DO UPDATE SET decision = EXCLUDED.decision, actor = EXCLUDED.actor, \
                           decided_at = NOW(), reason = EXCLUDED.reason",
        )
        .bind(uid)
        .bind(role)
        .bind(decision)
        .bind(&session.user_id)
        .bind(&artifacts.approval_reason)
        .execute(&mut *tx)
        .await
        .map_err(db_error)?;
    }

    tx.commit().await.map_err(db_error)?;
    // Best-effort notification emit, DETACHED from the request path. The lifecycle
    // transition is already durably committed; spawning the emit means a slow or
    // locked notifications table can neither roll back the transition NOR delay the
    // HTTP response into a timeout. Fail-open: errors are logged, never surfaced.
    // At-most-once: a crash before the task runs simply drops the convenience entry.
    {
        let pool: sqlx::PgPool = pool.clone();
        let action = action.to_string();
        let request_id = request_id.clone();
        let owner = current.created_by.clone();
        tokio::spawn(async move {
            if let Err(e) = crate::repos::notifications::emit_for_transition(
                &pool,
                &action,
                &request_id,
                owner.as_deref(),
            )
            .await
            {
                tracing::warn!(error = %e, request_id = %request_id, "post-commit notification emit failed (non-fatal)");
            }
        });
    }
    Ok(row)
}

/// The approval-route role a verified session satisfies, used as the
/// `request_approval_decisions.role` key. Picks the highest-precedence
/// approval-capable role the session carries; falls back to the verified
/// `user_id` when none is present (so the decision is still attributable and
/// the per-role UNIQUE still holds). Never client-supplied.
fn approval_role_for(session: &AuthSession) -> String {
    use ryuki_engine::auth::{APP_ROLE_DATACENTER_APPROVER, APP_ROLE_PLATFORM_ADMIN};
    if session
        .roles
        .iter()
        .any(|r| r == APP_ROLE_DATACENTER_APPROVER)
    {
        return APP_ROLE_DATACENTER_APPROVER.to_string();
    }
    if session.roles.iter().any(|r| r == APP_ROLE_PLATFORM_ADMIN) {
        return APP_ROLE_PLATFORM_ADMIN.to_string();
    }
    session.user_id.clone()
}

/// Best-effort audit of a DENIED transition attempt (a 403 before any state
/// change). Records to the DB when available, otherwise the process-local
/// store. The from/to stages are unknown without reading the row, so they are
/// recorded as "unknown"; a failure here never changes the 403 outcome.
async fn record_transition_denied(session: &AuthSession, request_id: &str, action: &str) {
    audit::record_denied(
        get_db(),
        session,
        &AuditRecord {
            action,
            request_id: Some(request_id),
            from_status: None,
            to_status: "unknown",
            from_stage: None,
            to_stage: "unknown",
            detail: json!({"note": "permission denied"}),
            outcome: "denied",
        },
    )
    .await;
}

/// Records an APPLIED transition to the process-local store (no-DB / dry-run
/// mode). The pre-transition status/stage are snapshotted by the caller BEFORE
/// it mutates the in-memory store and threaded through here, so the no-DB audit
/// trail carries the real from_status/from_stage (B8) instead of null.
#[allow(clippy::too_many_arguments)]
async fn record_local_transition(
    session: &AuthSession,
    request_id: &str,
    action: &str,
    from_status: Option<&str>,
    from_stage: Option<&str>,
    to_status: &str,
    to_stage: &str,
) {
    audit::record_audit_local(
        session,
        &AuditRecord {
            action,
            request_id: Some(request_id),
            from_status,
            to_status,
            from_stage,
            to_stage,
            detail: json!({}),
            outcome: "applied",
        },
    )
    .await;
}

fn map_engine_error(e: String) -> (StatusCode, Json<Value>) {
    status_400(&e)
}

fn parse_request_type(
    s: &str,
) -> Result<ryuki_engine::models::RequestType, (StatusCode, Json<Value>)> {
    use ryuki_engine::models::RequestType;
    match s {
        "server-deployment" => Ok(RequestType::ServerDeployment),
        "patch-maintenance" => Ok(RequestType::PatchMaintenance),
        "reboot-orchestration" => Ok(RequestType::RebootOrchestration),
        "controlled-restore" => Ok(RequestType::ControlledRestore),
        "zabbix-onboarding" => Ok(RequestType::ZabbixOnboarding),
        "cmdb-import" => Ok(RequestType::CmdbImport),
        "cmdb-update-export" => Ok(RequestType::CmdbUpdateExport),
        "operator-runbook-launch" => Ok(RequestType::OperatorRunbookLaunch),
        "application-environment-retirement" => Ok(RequestType::ApplicationEnvironmentRetirement),
        "vm-decommission-quarantine" => Ok(RequestType::VmDecommissionQuarantine),
        "request-preflight" => Ok(RequestType::RequestPreflight),
        "vm-day2-change" => Ok(RequestType::VmDay2Change),
        "snapshot-governance" => Ok(RequestType::SnapshotGovernance),
        "backup-coverage-report" => Ok(RequestType::BackupCoverageReport),
        _ => Err(status_400(&format!("Unknown request type: {}", s))),
    }
}

pub(crate) fn db_status_to_request_status(s: &str) -> ryuki_engine::models::RequestStatus {
    use ryuki_engine::models::RequestStatus;
    match s {
        "intake" => RequestStatus::Intake,
        "validated" => RequestStatus::Validated,
        "planned" => RequestStatus::Planned,
        "approved" => RequestStatus::Approved,
        "locked" => RequestStatus::Locked,
        "executing" | "executed" => RequestStatus::Executing,
        "verifying" | "verified" => RequestStatus::Verifying,
        "completed" => RequestStatus::Completed,
        "protecting" => RequestStatus::Protecting,
        "operational" => RequestStatus::Operational,
        "retired" => RequestStatus::Retired,
        "failed" => RequestStatus::Failed,
        "rejected" => RequestStatus::Rejected,
        "cancelled" => RequestStatus::Cancelled,
        _ => RequestStatus::Draft,
    }
}

fn request_status_to_db(s: &ryuki_engine::models::RequestStatus) -> &'static str {
    use ryuki_engine::models::RequestStatus;
    match s {
        RequestStatus::Draft => "draft",
        RequestStatus::Intake => "intake",
        RequestStatus::Validated => "validated",
        RequestStatus::Planned => "planned",
        RequestStatus::Approved => "approved",
        RequestStatus::Locked => "locked",
        RequestStatus::Executing => "executing",
        RequestStatus::Verifying => "verifying",
        RequestStatus::Completed => "completed",
        RequestStatus::Protecting => "protecting",
        RequestStatus::Operational => "operational",
        RequestStatus::Retired => "retired",
        RequestStatus::Failed => "failed",
        RequestStatus::Rejected => "rejected",
        RequestStatus::Cancelled => "cancelled",
    }
}

fn completed_request_stage(
    name: &str,
    evidence: Vec<ryuki_engine::models::EvidenceItem>,
) -> ryuki_engine::models::Stage {
    ryuki_engine::models::Stage {
        name: name.into(),
        status: ryuki_engine::models::StageStatus::Completed,
        started_at: None,
        completed_at: None,
        evidence,
        metadata: std::collections::HashMap::from([("dry_run".into(), "true".into())]),
    }
}

/// Payload/intake keys mirrored into `Request::metadata` for the resolver layer
/// (e.g. OS-based offering discrimination). Deliberately narrow: only these keys
/// are copied so the serialized `Request.metadata` surface is NOT broadened with
/// arbitrary intake fields. Keep in sync with the no-DB create path.
const METADATA_ALLOWLIST: &[&str] = &["operating_system"];

/// Extract the allowlisted string-valued keys from a request's payload JSONB
/// into a `HashMap<String, String>` suitable for `Request::metadata`.
///
/// Only `METADATA_ALLOWLIST` keys are copied (resolver inputs such as
/// `operating_system`); everything else in the payload is ignored so the
/// serialized request surface is unchanged. No schema migration needed.
fn payload_to_metadata(payload: &serde_json::Value) -> std::collections::HashMap<String, String> {
    let mut map = std::collections::HashMap::new();
    if let Some(obj) = payload.as_object() {
        for key in METADATA_ALLOWLIST {
            if let Some(s) = obj.get(*key).and_then(|v| v.as_str()) {
                map.insert((*key).to_string(), s.to_string());
            }
        }
    }
    map
}

/// Hydrate the engine `Request` from the persisted row. As of migration 047 the
/// stages/approval_route are the REAL durable history — no fabrication. This is
/// the point of P2: the engine guards (approve_request's
/// has_completed_stage("plan"), transition_status's
/// require_completed_stage_for_transition, execute_request's "execute" lookup)
/// now run against genuine persisted history, which is exactly why every
/// transition MUST persist its engine-produced stages back (see
/// apply_transition_audited / the per-handler artifacts).
fn db_row_to_request(row: &DbRequestRow, request_id: &str) -> ryuki_engine::models::Request {
    use ryuki_engine::models::{Request, Stage};
    Request {
        id: request_id.to_string(),
        offering_id: row.request_type.clone(),
        request_type: parse_request_type(&row.request_type)
            .unwrap_or(ryuki_engine::models::RequestType::RequestPreflight),
        status: db_status_to_request_status(&row.status),
        // From created_by (the verified SoD anchor), NOT row.name — row.name is
        // the request display name and was the source of the old
        // mis-reconstruction.
        requester: row
            .requester
            .clone()
            .or_else(|| row.created_by.clone())
            .unwrap_or_default(),
        owner: row
            .owner
            .clone()
            .or_else(|| row.created_by.clone())
            .unwrap_or_default(),
        site: row.site.clone(),
        environment: row.environment.clone(),
        criticality: row.criticality.clone(),
        // The REAL persisted lifecycle history.
        stages: serde_json::from_value::<Vec<Stage>>(row.stages.clone()).unwrap_or_default(),
        created_at: row.created_at.to_rfc3339(),
        updated_at: row.updated_at.to_rfc3339(),
        dry_run_required: true,
        approval_route: serde_json::from_value::<Vec<String>>(row.approval_route.clone())
            .unwrap_or_default(),
        evidence_manifest_id: row.evidence_manifest_id.clone(),
        // Extract string fields from the persisted payload JSONB into metadata
        // so that resolver logic (e.g. OS-based offering discrimination) has
        // access to them without requiring a schema migration.
        metadata: payload_to_metadata(&row.payload),
    }
}

/// Build the per-type payload JSONB stored in `requests.payload`. For
/// ServerDeployment the payload carries the VM-shaped fields incl cpu/memory_gb;
/// the other ~13 types have intake-thin bodies today, so they map to the common
/// envelope {name, site, environment, justification, criticality, request_type}.
/// This is the schemaless extension point: a type that later grows a richer
/// intake form extends its match arm WITHOUT a schema change.
fn build_request_payload(
    request_type: &ryuki_engine::models::RequestType,
    body: &CreateRequest,
    criticality: &str,
) -> Value {
    use ryuki_engine::models::RequestType;
    let mut payload = match request_type {
        RequestType::ServerDeployment => json!({
            "name": body.name,
            "cpu": body.cpu,
            "memory_gb": body.memory_gb,
            "site": body.site,
            "environment": body.environment,
            "justification": body.justification,
            "criticality": criticality,
            "request_type": body.request_type,
        }),
        _ => json!({
            "name": body.name,
            "site": body.site,
            "environment": body.environment,
            "justification": body.justification,
            "criticality": criticality,
            "request_type": body.request_type,
        }),
    };
    // Merge the per-type intake fields. `or_insert` ensures a client-supplied
    // field can NEVER overwrite a canonical key (name/site/environment/etc.).
    if let Some(object) = payload.as_object_mut() {
        for (key, value) in &body.fields {
            object
                .entry(key.clone())
                .or_insert_with(|| Value::String(value.clone()));
        }
    }
    payload
}

fn validation_failed_response(
    result: &ryuki_engine::models::ValidationResult,
) -> (StatusCode, Json<Value>) {
    (
        StatusCode::BAD_REQUEST,
        Json(json!({
            "error": "Validation failed",
            "validation": result,
        })),
    )
}

async fn requests_create(
    AuthExtractor(session): AuthExtractor,
    Json(body): Json<CreateRequest>,
) -> ApiResult {
    // Defense-in-depth: the central route gate also enforces "request" for
    // POST /api/requests. Keeping the handler check makes the requirement
    // explicit and survives any future routing refactor.
    if !check_permission(&session, "request") {
        // Audit the refused create (best-effort) before the 403.
        audit::record_denied(
            get_db(),
            &session,
            &AuditRecord {
                action: "request.create",
                request_id: None,
                from_status: None,
                to_status: "intake",
                from_stage: None,
                to_stage: "intake",
                detail: json!({}),
                outcome: "denied",
            },
        )
        .await;
        return Err(status_403());
    }
    let request_type = parse_request_type(&body.request_type)?;
    let mut request = request_lifecycle::create_request(
        &body.request_type,
        request_type.clone(),
        &body.name,
        &body.name,
        &body.site,
        &body.environment,
        "standard",
    )
    .map_err(map_engine_error)?;
    // Anchor the requester to the VERIFIED session principal, not the
    // client-supplied name. The DB path uses created_by=session.user_id; the
    // in-memory (no-DB) path must match so the cancel SoD check ("requester ==
    // caller") cannot be forged by setting the request name. Owner mirrors the
    // requester so the create response matches the persisted (created_by-backed)
    // value rather than echoing the request name.
    request.requester = session.user_id.clone();
    request.owner = session.user_id.clone();
    // Populate metadata from the allowlisted per-type intake fields so resolver
    // logic (OS-based offering discrimination) is available on the in-memory
    // path. Matches `payload_to_metadata` on the DB path — only METADATA_ALLOWLIST
    // keys are mirrored, never the whole intake form.
    for (k, v) in &body.fields {
        if METADATA_ALLOWLIST.contains(&k.as_str()) {
            request.metadata.insert(k.clone(), v.clone());
        }
    }

    if let Some(pool) = get_db() {
        let mut tx = pool.begin().await.map_err(db_error)?;
        // CreateRequest has no criticality field; default "standard", matching
        // the engine create_request call above.
        let criticality = "standard";
        // The full typed payload (authoritative for all 14 types) and the REAL
        // intake stage(s) the engine just produced. approval_route is '[]' at
        // intake; plan/validation_results stay NULL until those transitions.
        let payload = build_request_payload(&request_type, &body, criticality);
        let stages_json = serde_json::to_value(&request.stages).unwrap_or_else(|_| json!([]));
        let approval_route_json =
            serde_json::to_value(&request.approval_route).unwrap_or_else(|_| json!([]));
        // created_by is the VERIFIED requester principal from the session — it
        // is the requester anchor the cancel SoD check matches against. Never a
        // client-supplied value. requester/owner mirror it (the SoD anchor).
        let row = sqlx::query_as::<_, DbRequestRow>(&format!(
            "INSERT INTO requests \
             (request_type, site, environment, name, cpu, memory_gb, justification, created_by, \
              payload, stages, approval_route, criticality, requester, owner) \
             VALUES ($1, $2, $3, $4, $5, $6, $7, $8, $9::jsonb, $10::jsonb, $11::jsonb, $12, $8, $8) \
             RETURNING {REQUEST_COLUMNS}"
        ))
        .bind(&body.request_type)
        .bind(&body.site)
        .bind(&body.environment)
        .bind(&body.name)
        .bind(body.cpu as i32)
        .bind(body.memory_gb as i32)
        .bind(&body.justification)
        .bind(&session.user_id)
        .bind(&payload)
        .bind(&stages_json)
        .bind(&approval_route_json)
        .bind(criticality)
        .fetch_one(&mut *tx)
        .await
        .map_err(db_error)?;

        let request_id = row.id.to_string();
        audit::record_audit_tx(
            &mut tx,
            &session,
            &AuditRecord {
                action: "request.create",
                request_id: Some(&request_id),
                from_status: None,
                to_status: &row.status,
                from_stage: None,
                to_stage: &row.stage,
                detail: json!({}),
                outcome: "applied",
            },
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;

        let mut response = request;
        response.id = request_id;
        response.created_at = row.created_at.to_rfc3339();
        response.updated_at = row.updated_at.to_rfc3339();
        return Ok(Json(serde_json::to_value(&response).unwrap_or_default()));
    }

    audit::record_audit_local(
        &session,
        &AuditRecord {
            action: "request.create",
            request_id: Some(&request.id),
            from_status: None,
            to_status: request.status.as_str(),
            from_stage: None,
            to_stage: "intake",
            detail: json!({}),
            outcome: "applied",
        },
    )
    .await;
    request_store().lock().await.push(request.clone());
    Ok(Json(serde_json::to_value(&request).unwrap_or_default()))
}

/// Current lifecycle stage name for an in-memory request record: the first
/// stage that is not completed, the last stage when all are completed, or
/// "intake" when no stages exist (mirrors the requests.stage column default).
fn current_stage_name(request: &ryuki_engine::models::Request) -> String {
    request
        .stages
        .iter()
        .find(|stage| stage.status != ryuki_engine::models::StageStatus::Completed)
        .or_else(|| request.stages.last())
        .map(|stage| stage.name.clone())
        .unwrap_or_else(|| "intake".to_string())
}

async fn requests_list(Query(params): Query<PaginationParams>) -> Json<Value> {
    let limit = params.limit.unwrap_or(50).min(100);
    let offset = params.offset.unwrap_or(0);

    if let Some(pool) = get_db() {
        let rows: Vec<DbRequestRow> = sqlx::query_as(&format!(
            "SELECT {REQUEST_COLUMNS} FROM requests ORDER BY created_at DESC LIMIT $1 OFFSET $2"
        ))
        .bind(limit as i64)
        .bind(offset as i64)
        .fetch_all(pool)
        .await
        .unwrap_or_default();
        let summaries: Vec<Value> = rows
            .iter()
            .map(|r| {
                json!({
                    "request_id": r.id.to_string(),
                    "request_type": r.request_type,
                    "status": r.status,
                    "name": r.name,
                    "site": r.site,
                    "environment": r.environment,
                    "stage": r.stage,
                    "created_at": r.created_at.to_rfc3339()
                })
            })
            .collect();
        return Json(json!(summaries));
    }

    let store = request_store().lock().await;
    let summaries: Vec<Value> = store
        .iter()
        .skip(offset)
        .take(limit)
        .map(|r| {
            json!({
                "request_id": r.id,
                "request_type": r.request_type.to_string(),
                "status": r.status.as_str(),
                "name": r.requester,
                "site": r.site,
                "environment": r.environment,
                "stage": current_stage_name(r),
                "created_at": r.created_at
            })
        })
        .collect();
    Json(json!(summaries))
}

/// Sanitize persisted stage evidence before sending to the portal.
///
/// # Security
/// An `EvidenceItem` stores both `value` (raw runner output) and
/// `redacted_value` (the safe display form). For items with `redacted: true`
/// we MUST NOT send the raw `value` to the portal; we send the
/// `redacted_value` instead (or `"***REDACTED***"` when absent). This mirrors
/// the audit/evidence-pack redaction discipline and is the last safety net
/// before the data leaves the API process.
///
/// For items with `redacted: false` the raw `value` is passed through
/// unchanged — the runner's pre-scrub (`runner::scrub`) already ensured no
/// known secret appears in it.
///
/// The input is the raw JSONB stages value (a JSON array of Stage objects as
/// serialized by serde from `Vec<ryuki_engine::models::Stage>`). The output
/// replaces each evidence item's serialized `value` field with the safe form.
///
/// Non-array or malformed inputs are returned as-is (defensive; the DB should
/// always store a valid array).
fn sanitize_stages_for_portal(stages: &serde_json::Value) -> serde_json::Value {
    let Some(arr) = stages.as_array() else {
        return stages.clone();
    };
    let sanitized: Vec<serde_json::Value> = arr
        .iter()
        .map(|stage| {
            let Some(evidence_arr) = stage.get("evidence").and_then(|e| e.as_array()) else {
                // No evidence array — pass stage through unchanged.
                return stage.clone();
            };
            let sanitized_evidence: Vec<serde_json::Value> = evidence_arr
                .iter()
                .map(|item| {
                    let is_redacted = item
                        .get("redacted")
                        .and_then(|r| r.as_bool())
                        .unwrap_or(false);
                    if !is_redacted {
                        return item.clone();
                    }
                    // Redacted item: replace `value` with the safe display form.
                    let safe_value = item
                        .get("redacted_value")
                        .and_then(|v| v.as_str())
                        .unwrap_or("***REDACTED***");
                    let mut out = item.clone();
                    if let Some(obj) = out.as_object_mut() {
                        obj.insert(
                            "value".to_string(),
                            serde_json::Value::String(safe_value.to_string()),
                        );
                    }
                    out
                })
                .collect();
            let mut stage_out = stage.clone();
            if let Some(obj) = stage_out.as_object_mut() {
                obj.insert(
                    "evidence".to_string(),
                    serde_json::Value::Array(sanitized_evidence),
                );
            }
            stage_out
        })
        .collect();
    serde_json::Value::Array(sanitized)
}

/// POST /api/requests/{id}/approve-live-apply — admin approves the completed
/// LivePlan for this request and mints a CP-signed LiveApply grant (AWX bridge
/// slice 5c). It RECONSTRUCTS the LiveApply job from the latest SUCCEEDED
/// LivePlan agent_job's spec + evidence_digest, so the approver never
/// hand-builds the spec or the digest. The agent then INDEPENDENTLY verifies
/// the grant (digest match, request binding, expiry) before applying with
/// operator-provided creds. Admin-gated and mutation-authorizing — fail closed.
async fn requests_approve_live_apply(
    Path(request_id): Path<String>,
    AuthExtractor(session): AuthExtractor,
) -> ApiResult {
    if !check_permission(&session, "admin") {
        record_transition_denied(&session, &request_id, "request.approve-live-apply").await;
        return Err(status_403());
    }
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;

    // No-double-apply: at most ONE LiveApply may ever be approved per request.
    // This pre-check returns a friendly 409 if ANY LiveApply already exists for
    // it — active (Pending/Leased/Running), already-applied (Succeeded), or
    // stuck (ReconcileRequired/Failed). A failed or lease-expired apply must be
    // handled by the operator reconcile flow, NOT re-approved here. The
    // authoritative, concurrency-safe guard is in create_live_apply_job (an
    // ON CONFLICT against the partial unique index from migration 057), so even
    // a concurrent double-submit that races past this pre-check cannot mint a
    // second grant.
    let prior_apply: i64 = sqlx::query_scalar(
        "SELECT COUNT(*) FROM agent_jobs WHERE request_id = $1 AND mode = 'LiveApply'",
    )
    .bind(uid)
    .fetch_one(pool)
    .await
    .map_err(db_error)?;
    if prior_apply > 0 {
        return Err((
            StatusCode::CONFLICT,
            Json(json!({
                "error": "a live-apply has already been approved for this request; \
                          a failed or expired apply must be reconciled by an operator, \
                          not re-approved here"
            })),
        ));
    }

    #[derive(sqlx::FromRow)]
    struct PlanJobRow {
        platform: String,
        spec: serde_json::Value,
        evidence_digest: Option<String>,
        req_status: String,
    }
    // The latest TERMINAL, genuinely-successful LivePlan is what gets approved:
    // result_status 'planned' (terraform plan) or 'check_ok' (ansible --check),
    // with completed_at set — NOT merely job.status='Succeeded' (which also
    // maps from applied/verified results). JOIN requests both to prove
    // existence and to read the request's own status. Newest by COMPLETION.
    let plan: Option<PlanJobRow> = sqlx::query_as(
        "SELECT j.platform, j.spec, j.evidence_digest, r.status AS req_status \
         FROM agent_jobs j JOIN requests r ON r.id = j.request_id \
         WHERE j.request_id = $1 AND j.mode = 'LivePlan' \
           AND j.result_status IN ('planned', 'check_ok') \
           AND j.completed_at IS NOT NULL \
           AND j.evidence_digest IS NOT NULL \
         ORDER BY j.completed_at DESC, j.id DESC LIMIT 1",
    )
    .bind(uid)
    .fetch_optional(pool)
    .await
    .map_err(db_error)?;

    let Some(plan) = plan else {
        return Err((
            StatusCode::CONFLICT,
            Json(json!({
                "error": "no completed live plan to approve; run a live plan (mode=live-plan) first"
            })),
        ));
    };

    // A live apply must never be authorised once the request itself has
    // CONCLUDED — a terminal state (cancelled/rejected/completed/failed) OR the
    // post-completion governed lifecycle (protecting/operational). A stale plan
    // must not re-open such a request (its result backlink would no-op anyway).
    // is_concluded() is an exhaustive engine classifier, so a future status
    // variant fails closed here at compile time instead of slipping through.
    if db_status_to_request_status(&plan.req_status).is_concluded() {
        return Err((
            StatusCode::CONFLICT,
            Json(json!({
                "error": format!(
                    "request is in terminal state '{}'; cannot approve a live apply",
                    plan.req_status
                )
            })),
        ));
    }

    let digest = plan.evidence_digest.unwrap_or_default();

    // Reconstruct the spec from the approved plan, switching the mode to
    // LiveApply. approve_live_apply_with / create_live_apply_job re-validate
    // spec.mode == LiveApply, the 64-hex digest, the request_id binding, and
    // the expiry before signing the grant.
    let mut spec: ryuki_protocol::JobSpec = serde_json::from_value(plan.spec)
        .map_err(|e| status_400(&format!("stored plan spec is malformed: {e}")))?;
    spec.mode = ryuki_protocol::JobMode::LiveApply;

    let cp_key = crate::cp_identity::cp_signing_key().ok_or_else(|| {
        (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({"error": "control plane is not configured to sign grants"})),
        )
    })?;

    let body = crate::agents::ApproveLiveApplyBody {
        request_id: uid,
        platform: plan.platform,
        spec,
        approved_plan_digest: digest,
        // 1-hour grant TTL — the operator must apply within this window.
        expiry_seconds: 3600,
    };
    // Approver = the verified session principal (never the request body). Mints
    // the CP-signed grant + inserts the LiveApply job; the agent verifies the
    // grant independently before applying.
    crate::agents::approve_live_apply_with(pool, cp_key, session.user_id.as_str(), &body).await
}

/// GET /api/requests/{id}/execution-job — the execution-agent job dispatched
/// for this request (AWX bridge slice 3). Read-only AWX-style "job" view:
/// which agent ran it, the mode (dry-run/live), job + result status, the
/// evidence digest, and timestamps. The full (sanitized) evidence lives on the
/// request's stages via GET /api/requests/{id}; this surfaces the job itself.
/// 404 when no job has been dispatched (e.g. request not yet executed).
async fn requests_execution_job(Path(request_id): Path<String>) -> ApiResult {
    let Some(pool) = get_db() else {
        return Err(status_404(&request_id));
    };
    let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;

    #[derive(sqlx::FromRow)]
    struct ExecJobRow {
        id: Uuid,
        mode: String,
        status: String,
        result_status: Option<String>,
        evidence_digest: Option<String>,
        created_at: chrono::DateTime<chrono::Utc>,
        completed_at: Option<chrono::DateTime<chrono::Utc>>,
    }
    // JOIN requests so a synthetic/orphan agent_jobs.request_id (the column is
    // not FK-constrained and migrations seed fixtures) cannot surface job
    // metadata for a request that does not exist — match requests_get's 404.
    // Latest job wins (a re-dispatch supersedes), deterministic on (created_at,
    // id). agent_id is intentionally NOT exposed: it is self-declared fleet
    // identity, surfaced only via the admin-gated agents view.
    let row: Option<ExecJobRow> = sqlx::query_as(
        "SELECT j.id, j.mode, j.status, j.result_status, j.evidence_digest, \
         j.created_at, j.completed_at \
         FROM agent_jobs j JOIN requests r ON r.id = j.request_id \
         WHERE j.request_id = $1 \
         ORDER BY j.created_at DESC, j.id DESC LIMIT 1",
    )
    .bind(uid)
    .fetch_optional(pool)
    .await
    .map_err(db_error)?;

    let Some(j) = row else {
        return Err(status_404(&request_id));
    };
    Ok(Json(json!({
        "request_id": request_id,
        "agent_job_id": j.id.to_string(),
        "mode": j.mode,
        "status": j.status,
        "result_status": j.result_status,
        "evidence_digest": j.evidence_digest,
        "created_at": j.created_at.to_rfc3339(),
        "completed_at": j.completed_at.map(|t| t.to_rfc3339()),
        "source": "database",
    })))
}

async fn requests_get(Path(request_id): Path<String>) -> ApiResult {
    if let Some(pool) = get_db() {
        let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;
        let row: DbRequestRow = sqlx::query_as(&format!(
            "SELECT {REQUEST_COLUMNS} FROM requests WHERE id = $1"
        ))
        .bind(uid)
        .fetch_optional(pool)
        .await
        .map_err(|e| {
            (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({"error": e.to_string()})),
            )
        })?
        .ok_or_else(|| status_404(&request_id))?;
        // The durable lifecycle state (047): payload is authoritative for all
        // 14 types; stages/approval_route/plan/validation_results are the REAL
        // persisted history that survives a restart (no fabrication).
        //
        // Sanitize stages before sending to the portal: for any evidence item
        // with redacted:true the raw `value` is replaced by the safe
        // `redacted_value` (or "***REDACTED***"). The plan JSONB is also a
        // Vec<Stage> and receives the same treatment.
        let sanitized_stages = sanitize_stages_for_portal(&row.stages);
        let sanitized_plan = sanitize_stages_for_portal(&row.plan);
        return Ok(Json(json!({
            "request_id": row.id.to_string(),
            "request_type": row.request_type,
            "status": row.status,
            "stage": row.stage,
            "site": row.site,
            "environment": row.environment,
            "name": row.name,
            "cpu": row.cpu,
            "memory_gb": row.memory_gb,
            "justification": row.justification,
            "created_by": row.created_by,
            "created_at": row.created_at.to_rfc3339(),
            "updated_at": row.updated_at.to_rfc3339(),
            "payload": row.payload,
            "stages": sanitized_stages,
            "approval_route": row.approval_route,
            "plan": sanitized_plan,
            "validation_results": row.validation_results,
            "criticality": row.criticality,
            "requester": row.requester,
            "owner": row.owner,
            "evidence_manifest_id": row.evidence_manifest_id
        })));
    }

    let store = request_store().lock().await;
    let record = store.iter().find(|r| r.id == request_id);
    match record {
        Some(r) => {
            // Sanitize in-memory request stages/plan before sending to portal,
            // applying the same redaction discipline as the DB path.
            let mut val = serde_json::to_value(r).unwrap_or_default();
            if let Some(obj) = val.as_object_mut() {
                if let Some(stages_val) = obj.get("stages").cloned() {
                    obj.insert(
                        "stages".to_string(),
                        sanitize_stages_for_portal(&stages_val),
                    );
                }
                if let Some(plan_val) = obj.get("plan").cloned() {
                    obj.insert("plan".to_string(), sanitize_stages_for_portal(&plan_val));
                }
            }
            Ok(Json(val))
        }
        None => Err(status_404(&request_id)),
    }
}

async fn requests_validate(
    Path(request_id): Path<String>,
    AuthExtractor(session): AuthExtractor,
) -> ApiResult {
    // Defense-in-depth: validate is operator-tier ("execute"). The central
    // route gate enforces the same requirement.
    if !check_permission(&session, "execute") {
        record_transition_denied(&session, &request_id, "request.validate").await;
        return Err(status_403());
    }
    if let Some(pool) = get_db() {
        let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;
        let current: DbRequestRow = sqlx::query_as(&format!(
            "SELECT {REQUEST_COLUMNS} FROM requests WHERE id = $1"
        ))
        .bind(uid)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&request_id))?;

        let request = db_row_to_request(&current, &request_id);
        let result = request_lifecycle::validate_request(&request).map_err(map_engine_error)?;

        if !result.passed {
            return Err(validation_failed_response(&result));
        }

        // Persist the cumulative stages with the completed "validate" stage
        // appended (mirroring the no-DB arm) plus the validation result, so a
        // restart preserves the validated lifecycle, not just the status flip.
        let mut validated = request.clone();
        validated
            .stages
            .push(completed_request_stage("validate", Vec::new()));
        let stages_json = serde_json::to_value(&validated.stages).unwrap_or_else(|_| json!([]));
        let validation_json = serde_json::to_value(&result).unwrap_or(Value::Null);

        let db_status = request_status_to_db(&ryuki_engine::models::RequestStatus::Validated);
        apply_transition_audited(
            pool,
            &session,
            uid,
            &current,
            "request.validate",
            &current.status,
            db_status,
            "validate",
            json!({}),
            TransitionArtifacts {
                stages_json,
                plan_json: None,
                validation_json: Some(validation_json),
                approval_route_json: None,
                approval_role: None,
                approval_decision: None,
                approval_reason: None,
            },
        )
        .await?;

        return Ok(Json(serde_json::to_value(&result).unwrap_or_default()));
    }

    let mut store = request_store().lock().await;
    let idx = store
        .iter()
        .position(|r| r.id == request_id)
        .ok_or_else(|| status_404(&request_id))?;

    let result = request_lifecycle::validate_request(&store[idx]).map_err(map_engine_error)?;

    if !result.passed {
        store[idx].stages.push(ryuki_engine::models::Stage {
            name: "validate".into(),
            status: ryuki_engine::models::StageStatus::Failed,
            started_at: Some(now_iso()),
            completed_at: Some(now_iso()),
            evidence: Vec::new(),
            metadata: std::collections::HashMap::from([(
                "failed_rules".into(),
                result.failed_rules.join(","),
            )]),
        });
        store[idx].updated_at = now_iso();
        return Err(validation_failed_response(&result));
    }

    // B8: snapshot the prior status/stage BEFORE mutating store[idx] so the
    // no-DB audit row carries the real from_status/from_stage.
    let from_status = request_status_to_db(&store[idx].status).to_string();
    let from_stage = current_stage_name(&store[idx]);
    store[idx].status = ryuki_engine::models::RequestStatus::Validated;
    store[idx].stages.push(ryuki_engine::models::Stage {
        name: "validate".into(),
        status: ryuki_engine::models::StageStatus::Completed,
        started_at: Some(now_iso()),
        completed_at: Some(now_iso()),
        evidence: Vec::new(),
        metadata: std::collections::HashMap::new(),
    });
    store[idx].updated_at = now_iso();
    record_local_transition(
        &session,
        &request_id,
        "request.validate",
        Some(&from_status),
        Some(&from_stage),
        "validated",
        "validate",
    )
    .await;

    Ok(Json(serde_json::to_value(&result).unwrap_or_default()))
}

// Enrich the plan stages produced by `plan_request` with Terraform dry-run
// evidence items, if the offering has wired IaC.
//
// Enrichment logic:
// 1. Resolve the IaC bundle for `offering_id`. If None, return immediately
//    (unwired offering — no change at all).
// 2. Build a TerraformRunner with the embedded IaC and call run_dry with
//    empty ResolvedCredentials (server-deployment vsphere IaC needs no
//    secrets for validate; plan would need them for a live vCenter).
// 3. run_dry now runs: init → validate (always) → plan (best-effort).
//    - status Planned  → append "terraform-validate" + "terraform-plan" items.
//    - status Validated → append "terraform-validate" item only (plan requires
//      live vCenter, not available offline).
//    - other status → append "terraform-plan-note" (skip note). Never error.
//
// Soundness invariant:
// Callers MUST call this function BEFORE building stages_json/plan_json
// for the DB write. Enriching after serialization loses the output.

// ---------------------------------------------------------------------------
// Shared evidence builders
// ---------------------------------------------------------------------------

/// Build the `EvidenceItem` list for a Terraform dry-run result.
///
/// Maps:
/// - `Ok(outcome)` with `status == Planned` → two items:
///   1. `"terraform-validate"` item: "configuration is valid"
///   2. `"terraform-plan"` item with summary + UTF-8-safe truncated log (4 KiB).
/// - `Ok(outcome)` with `status == Validated` → one item:
///   1. `"terraform-validate"` item: "configuration is valid; plan requires live
///      provider (vsphere/vCenter not reachable offline)".
/// - `Ok(outcome)` with any other status → one item:
///   `"terraform-plan-note"` (runner unavailable or failed).
/// - `Err(e)` → one item: `"terraform-plan-note"` (skipped: {e}).
///
/// This is the single source of truth for evidence construction; both the
/// synchronous inner function and the async wrapper call it so the two paths
/// cannot drift.
fn terraform_evidence_items(
    result: Result<ryuki_engine::runners::RunOutcome, ryuki_engine::runners::RunnerError>,
) -> Vec<ryuki_engine::models::EvidenceItem> {
    use ryuki_engine::models::{EvidenceItem, EvidenceType};
    use ryuki_engine::runners::RunStatus;

    /// Truncate a log to ~4 KiB on a UTF-8 char boundary.
    fn truncate_log(log: &str) -> String {
        if log.len() > 4096 {
            let truncated: String = log.chars().take(4096).collect();
            format!("{truncated}...[truncated]")
        } else {
            log.to_string()
        }
    }

    match result {
        Ok(outcome) if outcome.status == RunStatus::Planned => {
            // Both validate and plan succeeded.
            // Emit validate item + plan item.
            let log_excerpt = truncate_log(&outcome.log);
            let plan_value = if log_excerpt.is_empty() {
                outcome.summary.clone()
            } else {
                format!("{}\n\n{}", outcome.summary, log_excerpt)
            };
            vec![
                EvidenceItem {
                    key: "terraform-validate".to_string(),
                    value: "configuration is valid".to_string(),
                    redacted_value: None,
                    redacted: false,
                    evidence_type: EvidenceType::Plan,
                },
                EvidenceItem {
                    key: "terraform-plan".to_string(),
                    value: plan_value,
                    redacted_value: None,
                    redacted: false,
                    evidence_type: EvidenceType::Plan,
                },
            ]
        }
        Ok(outcome) if outcome.status == RunStatus::Validated => {
            // Validate passed; plan requires a live provider (e.g. vCenter).
            // Emit validate item only — plan is deferred until live execution.
            let log_excerpt = truncate_log(&outcome.log);
            let value = format!(
                "configuration is valid; plan requires live provider \
                 (vsphere/vCenter not reachable offline)\n\n{}",
                log_excerpt.trim()
            );
            vec![EvidenceItem {
                key: "terraform-validate".to_string(),
                value,
                redacted_value: None,
                redacted: false,
                evidence_type: EvidenceType::Plan,
            }]
        }
        Ok(outcome) => vec![EvidenceItem {
            // RunnerUnavailable or Failed — degrade gracefully.
            key: "terraform-plan-note".to_string(),
            value: format!(
                "terraform plan skipped: runner unavailable or failed (status: {}; {})",
                outcome.status, outcome.summary
            ),
            redacted_value: None,
            redacted: false,
            evidence_type: EvidenceType::Plan,
        }],
        Err(e) => vec![EvidenceItem {
            // Workspace, spawn, or timeout error — degrade gracefully.
            key: "terraform-plan-note".to_string(),
            value: format!("terraform plan skipped: {e}"),
            redacted_value: None,
            redacted: false,
            evidence_type: EvidenceType::Plan,
        }],
    }
}

/// Build the `EvidenceItem` for an Ansible dry-run (--check) result.
///
/// Maps:
/// - `Ok(outcome)` with `status == CheckOk` → `"ansible-check"` item with
///   summary + UTF-8-safe truncated log (4 KiB).
/// - `Ok(outcome)` with any other status → `"ansible-check-note"` item
///   (runner unavailable or failed).
/// - `Err(e)` → `"ansible-check-note"` item (skipped: {e}).
///
/// Single source of truth used by both the sync inner function and the async
/// wrapper so the two paths cannot drift.
fn ansible_evidence_item(
    result: Result<ryuki_engine::runners::RunOutcome, ryuki_engine::runners::RunnerError>,
) -> ryuki_engine::models::EvidenceItem {
    use ryuki_engine::models::{EvidenceItem, EvidenceType};
    use ryuki_engine::runners::RunStatus;

    match result {
        Ok(outcome) if outcome.status == RunStatus::CheckOk => {
            let log_excerpt = if outcome.log.len() > 4096 {
                let truncated: String = outcome.log.chars().take(4096).collect();
                format!("{truncated}...[truncated]")
            } else {
                outcome.log.clone()
            };
            let value = if log_excerpt.is_empty() {
                outcome.summary.clone()
            } else {
                format!("{}\n\n{}", outcome.summary, log_excerpt)
            };
            EvidenceItem {
                key: "ansible-check".to_string(),
                value,
                redacted_value: None,
                redacted: false,
                evidence_type: EvidenceType::Summary,
            }
        }
        Ok(outcome) => EvidenceItem {
            // RunnerUnavailable or Failed — degrade gracefully.
            key: "ansible-check-note".to_string(),
            value: format!(
                "ansible --check skipped: runner unavailable or failed (status: {}; {})",
                outcome.status, outcome.summary
            ),
            redacted_value: None,
            redacted: false,
            evidence_type: EvidenceType::Summary,
        },
        Err(e) => EvidenceItem {
            // Workspace, spawn, or timeout error — degrade gracefully.
            key: "ansible-check-note".to_string(),
            value: format!("ansible --check skipped: {e}"),
            redacted_value: None,
            redacted: false,
            evidence_type: EvidenceType::Summary,
        },
    }
}

// ---------------------------------------------------------------------------
// Synchronous inner implementations
// ---------------------------------------------------------------------------

/// Synchronous inner implementation of terraform plan enrichment.
///
/// Extracted so that:
/// - Tests (which may be sync) can call this directly and exercise the shared
///   `terraform_evidence_items` builder.
/// - The async wrapper can offload `run_dry` via `spawn_blocking` and then
///   call the same builder on the result.
#[cfg_attr(not(test), allow(dead_code))]
fn enrich_plan_stages_with_terraform_sync(
    request: &ryuki_engine::models::Request,
    stages: &mut [ryuki_engine::models::Stage],
) {
    use crate::integration::ResolvedCredentials;
    use ryuki_engine::runners::{RunMode, RunPlan};
    use ryuki_runner::iac;
    use ryuki_runner::terraform::TerraformRunner;
    use ryuki_runner::Runner;

    // Resolve the effective offering_id via the OS-discriminating resolver.
    // For server-deployment this maps to linux- or windows- by OS metadata;
    // for controlled-restore this normalises the catalog name mismatch.
    let offering_id = iac::resolve_offering_id(request);
    let offering_id = offering_id.as_str();

    // Step 1: resolve IaC bundle — if None, no wiring for this offering.
    let Some(iac_bundle) = iac::resolve(offering_id) else {
        return;
    };

    // Step 2: build runner with embedded IaC and invoke dry-run. The request's
    // site/environment/id flow in as non-secret Terraform vars (the runner
    // writes them to a tfvars JSON file, never argv) so the plan reflects the
    // real request instead of the IaC defaults.
    let runner = TerraformRunner::new().with_iac(iac_bundle);
    let mut vars = std::collections::BTreeMap::new();
    vars.insert("site".to_string(), request.site.clone());
    vars.insert("environment".to_string(), request.environment.clone());
    vars.insert("request_id".to_string(), request.id.clone());
    let run_plan = RunPlan {
        runner_kind: ryuki_engine::runners::RunnerKind::Terraform,
        mode: RunMode::DryRun,
        offering_id: offering_id.to_string(),
        vars,
        secret_var_names: Vec::new(),
    };
    let empty_creds = ResolvedCredentials {
        material: Vec::new(),
        descriptor: "none".to_string(),
    };

    // Step 3/4: delegate result→EvidenceItem list mapping to the shared builder,
    // then extend the "plan" stage. The stage is always present (plan_request
    // guarantees it), but we guard defensively.
    let evidence_items = terraform_evidence_items(runner.run_dry(&run_plan, &empty_creds));
    if let Some(plan_stage) = stages.iter_mut().find(|s| s.name == "plan") {
        plan_stage.evidence.extend(evidence_items);
    }
}

/// Async wrapper: moves the blocking `runner.run_dry` call off the tokio
/// executor thread via `spawn_blocking` so a slow/hung terraform subprocess
/// does not starve other async tasks.
///
/// The stages mutation still happens on the async task after the blocking call
/// returns — only the subprocess wait is offloaded.
///
/// # Graceful degradation on JoinError
/// If the blocking task panics (e.g. OOM inside the subprocess), the panic is
/// caught here and a note item is appended instead of propagating the panic.
/// The JoinError path builds the note inline (distinct message); all other
/// result variants go through `terraform_evidence_items`.
async fn enrich_plan_stages_with_terraform(
    request: &ryuki_engine::models::Request,
    stages: &mut [ryuki_engine::models::Stage],
) {
    use crate::integration::ResolvedCredentials;
    use ryuki_engine::models::{EvidenceItem, EvidenceType};
    use ryuki_engine::runners::{RunMode, RunPlan};
    use ryuki_runner::iac;
    use ryuki_runner::terraform::TerraformRunner;
    use ryuki_runner::Runner;

    // Resolve offering_id before entering spawn_blocking (cheap, borrows request).
    let offering_id = iac::resolve_offering_id(request);
    let offering_id_str = offering_id.clone();

    // Resolve IaC bundle — if None, no wiring for this offering.
    let Some(iac_bundle) = iac::resolve(&offering_id_str) else {
        return;
    };

    // Build all owned values before entering spawn_blocking (no borrows cross
    // the thread boundary).
    let runner = TerraformRunner::new().with_iac(iac_bundle);
    let mut vars = std::collections::BTreeMap::new();
    vars.insert("site".to_string(), request.site.clone());
    vars.insert("environment".to_string(), request.environment.clone());
    vars.insert("request_id".to_string(), request.id.clone());
    let run_plan = RunPlan {
        runner_kind: ryuki_engine::runners::RunnerKind::Terraform,
        mode: RunMode::DryRun,
        offering_id: offering_id_str.clone(),
        vars,
        secret_var_names: Vec::new(),
    };
    let empty_creds = ResolvedCredentials {
        material: Vec::new(),
        descriptor: "none".to_string(),
    };

    // Offload the blocking subprocess call to a dedicated thread so the tokio
    // worker is not blocked for the duration of terraform init + plan.
    let run_result =
        tokio::task::spawn_blocking(move || runner.run_dry(&run_plan, &empty_creds)).await;

    // Unpack the JoinResult<Result<RunOutcome, RunnerError>>.
    // JoinError (spawn_blocking panic) gets an inline note with a distinct
    // message. All other variants go through the shared builder.
    let evidence_items: Vec<ryuki_engine::models::EvidenceItem> = match run_result {
        Err(_join_err) => vec![EvidenceItem {
            key: "terraform-plan-note".to_string(),
            value: "terraform plan skipped: internal error (spawn_blocking panic)".to_string(),
            redacted_value: None,
            redacted: false,
            evidence_type: EvidenceType::Plan,
        }],
        Ok(result) => terraform_evidence_items(result),
    };

    if let Some(plan_stage) = stages.iter_mut().find(|s| s.name == "plan") {
        plan_stage.evidence.extend(evidence_items);
    }
}

