#[derive(serde::Deserialize, Default)]
struct ExecuteParams {
    /// Requested execution mode: omitted / "offline-dry-run" / "dry-run"
    /// (default), "live-plan" (privileged), or "live-apply" (rejected here —
    /// requires a CP-signed approval grant).
    mode: Option<String>,
}

async fn requests_execute(
    Path(request_id): Path<String>,
    Query(params): Query<ExecuteParams>,
    AuthExtractor(session): AuthExtractor,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        record_transition_denied(&session, &request_id, "request.execute").await;
        return Err(status_403());
    }
    // Resolve the requested execution mode (default: offline dry-run — the safe
    // AWX "check" equivalent). LivePlan (a real terraform plan / ansible --check
    // against a backend; NO mutation) additionally requires the `admin`
    // permission. LiveApply mutates and is NOT dispatchable here: it requires a
    // CP-signed approval grant minted via the dedicated operator endpoint, so
    // the caller is routed there rather than silently dispatching a mutation.
    let (mode, mode_label) = match params.mode.as_deref() {
        None | Some("") | Some("offline-dry-run") | Some("dry-run") | Some("offline") => {
            (ryuki_protocol::JobMode::OfflineDryRun, "OfflineDryRun")
        }
        Some("live-plan") => {
            if !check_permission(&session, "admin") {
                record_transition_denied(&session, &request_id, "request.execute.live-plan").await;
                return Err(status_403());
            }
            (ryuki_protocol::JobMode::LivePlan, "LivePlan")
        }
        Some("live-apply") => {
            return Err(status_400(
                "live-apply is not dispatchable via execute; an operator must mint a \
                 CP-signed approval grant via POST /api/admin/agents/live-apply-jobs",
            ));
        }
        Some(other) => return Err(status_400(&format!("unknown execution mode: {other}"))),
    };
    if let Some(pool) = get_db() {
        let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;
        let current: DbRequestRow = sqlx::query_as(&format!(
            "SELECT {REQUEST_COLUMNS} FROM requests WHERE id = $1"
        ))
        .bind(uid)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&request_id))?;

        let request = db_row_to_request(&current, &request_id);

        // AWX-style dispatch: transition Locked -> Executing (execute stage
        // In-Progress) and enqueue an agent_job (in the resolved mode) that an
        // execution agent will run. The agent's signed result completes the stage
        // and advances the request (see the post_job_result backlink). The
        // status CAS, the agent_jobs INSERT, and the audit row are written in
        // ONE transaction, so a dispatched request always has its job and a
        // job always has a dispatched request.
        let executing = request_lifecycle::begin_execution(&request).map_err(map_engine_error)?;
        let stages_json = serde_json::to_value(&executing.stages).unwrap_or_else(|_| json!([]));

        // Dry-run job spec from the request. iac_digest is a stub here; a real
        // content digest is produced once a live IaC resolver computes it
        // (operator-owned). vars carry the request's non-secret metadata.
        let offering = ryuki_runner::iac::resolve_offering_id(&request);
        let spec = ryuki_protocol::JobSpec {
            request_id: uid,
            offering_id: Uuid::new_v4(),
            iac_ref: offering,
            iac_digest: "0".repeat(64),
            vars: request
                .metadata
                .iter()
                .map(|(k, v)| (k.clone(), v.clone()))
                .collect(),
            mode,
        };
        let spec_json = serde_json::to_value(&spec).unwrap_or_default();
        let platform = request.site.clone();

        let mut tx = pool.begin().await.map_err(db_error)?;
        let updated: Option<DbRequestRow> = sqlx::query_as(&format!(
            "UPDATE requests SET status = 'executing', stage = 'execute', \
             stages = $2::jsonb, updated_at = NOW() \
             WHERE id = $1 AND status = 'locked' RETURNING {REQUEST_COLUMNS}"
        ))
        .bind(uid)
        .bind(&stages_json)
        .fetch_optional(&mut *tx)
        .await
        .map_err(db_error)?;
        let Some(row) = updated else {
            // Concurrent transition won the CAS (status was no longer Locked).
            tx.rollback().await.ok();
            return Err(transition_conflict_409(&request_id));
        };
        let job_id: Uuid = sqlx::query_scalar(
            "INSERT INTO agent_jobs (request_id, platform, spec, mode) \
             VALUES ($1, $2, $3, $4) RETURNING id",
        )
        .bind(uid)
        .bind(&platform)
        .bind(&spec_json)
        .bind(mode_label)
        .fetch_one(&mut *tx)
        .await
        .map_err(db_error)?;
        audit::record_audit_tx(
            &mut tx,
            &session,
            &AuditRecord {
                action: "request.execute",
                request_id: Some(&request_id),
                from_status: Some(&current.status),
                to_status: &row.status,
                from_stage: Some(&current.stage),
                to_stage: "execute",
                detail: json!({
                    "agent_job_id": job_id,
                    "mode": mode_label,
                    "platform": platform.clone(),
                }),
                outcome: "dispatched",
            },
        )
        .await
        .map_err(db_error)?;
        tx.commit().await.map_err(db_error)?;

        return Ok(Json(json!({
            "request_id": request_id,
            "agent_job_id": job_id,
            "status": row.status,
            "stage": "execute",
            "mode": mode_label,
            "platform": platform,
            "source": "database",
            "note": "dispatched to execution agent",
        })));
    }

    let mut store = request_store().lock().await;
    let idx = store
        .iter()
        .position(|r| r.id == request_id)
        .ok_or_else(|| status_404(&request_id))?;

    let executed = request_lifecycle::execute_request(&store[idx]).map_err(map_engine_error)?;

    // B8: snapshot prior status/stage before overwriting store[idx].
    let from_status = request_status_to_db(&store[idx].status).to_string();
    let from_stage = current_stage_name(&store[idx]);
    let to_status = executed.status.as_str();
    store[idx] = executed.clone();
    record_local_transition(
        &session,
        &request_id,
        "request.execute",
        Some(&from_status),
        Some(&from_stage),
        to_status,
        "execute",
    )
    .await;

    Ok(Json(serde_json::to_value(&executed).unwrap_or_default()))
}

async fn requests_verify(
    Path(request_id): Path<String>,
    AuthExtractor(session): AuthExtractor,
) -> ApiResult {
    if !check_permission(&session, "execute") {
        record_transition_denied(&session, &request_id, "request.verify").await;
        return Err(status_403());
    }
    if let Some(pool) = get_db() {
        let uid = Uuid::parse_str(&request_id).map_err(|_| status_404(&request_id))?;
        let current: DbRequestRow = sqlx::query_as(&format!(
            "SELECT {REQUEST_COLUMNS} FROM requests WHERE id = $1"
        ))
        .bind(uid)
        .fetch_optional(pool)
        .await
        .map_err(db_error)?
        .ok_or_else(|| status_404(&request_id))?;

        let request = db_row_to_request(&current, &request_id);
        let evidence = request_lifecycle::verify_request(&request).map_err(map_engine_error)?;
        let mut verified_request = request.clone();
        verified_request
            .stages
            .push(completed_request_stage("verify", evidence.clone()));

        // Enrich verify stage with real ansible --check output for wired
        // offerings. MUST happen before stages_json serialization (soundness
        // invariant). The async wrapper offloads the blocking subprocess.
        // Graceful degradation: ansible absent/fails/times out → note item.
        // No DB transaction is held here — TX is opened inside
        // apply_transition_audited AFTER the enrich completes.
        enrich_verify_stages_with_ansible(&request, &mut verified_request.stages).await;

        let completed = request_lifecycle::transition_status(
            &verified_request,
            ryuki_engine::models::RequestStatus::Completed,
        )
        .map_err(map_engine_error)?;

        let stages_json =
            serde_json::to_value(&verified_request.stages).unwrap_or_else(|_| json!([]));
        let db_status = request_status_to_db(&completed.status);
        apply_transition_audited(
            pool,
            &session,
            uid,
            &current,
            "request.verify",
            &current.status,
            db_status,
            "verify",
            json!({}),
            TransitionArtifacts::stages_only(stages_json),
        )
        .await?;

        return Ok(Json(serde_json::to_value(&evidence).unwrap_or_default()));
    }

    // ── No-DB branch (Task 3 restructure) ───────────────────────────────────
    // Same pattern as requests_plan: clone+drop → enrich (async) → re-lock+rewrite.

    // Step 1: clone + release lock.
    let cloned_request = {
        let store = request_store().lock().await;
        let idx = store
            .iter()
            .position(|r| r.id == request_id)
            .ok_or_else(|| status_404(&request_id))?;
        store[idx].clone()
        // guard drops here
    };

    // Step 2: compute evidence + build verified_request + enrich — no lock held.
    let evidence = request_lifecycle::verify_request(&cloned_request).map_err(map_engine_error)?;
    let mut verified_request = cloned_request.clone();
    verified_request
        .stages
        .push(completed_request_stage("verify", evidence.clone()));
    enrich_verify_stages_with_ansible(&cloned_request, &mut verified_request.stages).await;

    let completed = request_lifecycle::transition_status(
        &verified_request,
        ryuki_engine::models::RequestStatus::Completed,
    )
    .map_err(map_engine_error)?;

    // Step 3: re-acquire, re-find, write completed result.
    let mut store = request_store().lock().await;
    let idx = store
        .iter()
        .position(|r| r.id == request_id)
        .ok_or_else(|| status_404(&request_id))?;

    // Optimistic-concurrency guard: the request must still be in the pre-state
    // the verify was computed against. If a concurrent transition changed it
    // between the clone and this re-lock, do NOT overwrite it — return 409,
    // mirroring the DB CAS path. (The store lock is released across the
    // subprocess, so this window is real.)
    if store[idx].status != cloned_request.status {
        return Err(status_409(&format!(
            "request {request_id} was modified concurrently during verification; retry"
        )));
    }

    // B8: snapshot prior status/stage before overwriting store[idx].
    let from_status = request_status_to_db(&store[idx].status).to_string();
    let from_stage = current_stage_name(&store[idx]);
    let to_status = completed.status.as_str().to_string();
    store[idx] = completed;
    drop(store);

    record_local_transition(
        &session,
        &request_id,
        "request.verify",
        Some(&from_status),
        Some(&from_stage),
        &to_status,
        "verify",
    )
    .await;

    Ok(Json(serde_json::to_value(&evidence).unwrap_or_default()))
}

