async fn firmware_request_exception(
    Extension(session): Extension<AuthSession>,
    Json(body): Json<FirmwareExceptionRequest>,
) -> Result<Json<Value>, (StatusCode, Json<Value>)> {
    // approved_by = authenticated caller (from request extensions), never a client
    // body field — the exception's approval must name the real principal.
    // Pure validation first (engine guard).
    firmware_lifecycle::validate_exception_request(
        &body.reason,
        &session.user_id,
        body.expiry_days,
    )
    .map_err(|e| status_400(&e))?;
    let pool = get_db().ok_or_else(status_503_no_db)?;
    let exception = crate::repos::firmware_lifecycle::request_exception(
        pool,
        &body.device_id,
        &body.reason,
        &session.user_id,
        body.expiry_days,
    )
    .await
    .map_err(db_error)?
    .ok_or_else(|| status_404(&body.device_id))?;
    Ok(Json(json!({
        "source": "live",
        "exception": exception,
        "device_status": firmware_lifecycle::ComplianceStatus::Exception.to_string()
    })))
}

