// Run with: RYUKI_DATABASE_URL=<url> cargo test -p ryuki-api --bins runbook_executions_db_tests -- --test-threads=1
#[cfg(test)]
mod runbook_executions_db_tests {
    use crate::database::DB_TEST_SERIAL;
    use sqlx::PgPool;

    async fn global_pool() -> Option<&'static PgPool> {
        let url = std::env::var("RYUKI_DATABASE_URL").ok()?;
        if url.is_empty() {
            return None;
        }
        crate::database::try_connect_with_url(&url, 5, 1, 300, 30, 1800).await;
        let pool = crate::database::get_db()?;
        crate::database::run_migrations(pool).await.ok()?;
        Some(pool)
    }

    async fn cleanup(pool: &PgPool, id: &str) {
        sqlx::query("DELETE FROM runbook_executions WHERE id = $1")
            .bind(id)
            .execute(pool)
            .await
            .ok();
    }

    fn make_exec(
        suffix: &str,
        runbook_id: &str,
        site: &str,
    ) -> ryuki_engine::runbook_execution::RunbookExecution {
        ryuki_engine::runbook_execution::build_execution(
            runbook_id,
            site,
            &format!("test.engineer-{suffix}"),
        )
        .expect("build_execution must succeed for known inputs")
    }

    /// Full lifecycle: start -> approve -> complete.
    /// Each transition must be persisted; re-get returns the updated status.
    #[tokio::test]
    async fn test_full_lifecycle() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let exec = make_exec(&suffix, "restart-service", "DEFRA");
        let id = exec.id.clone();

        // 1. Insert (start)
        crate::repos::runbook_executions::insert(pool, &exec)
            .await
            .expect("insert must succeed");

        let (fetched, version) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get failed")
            .expect("execution not found after insert");
        assert_eq!(
            fetched.status,
            ryuki_engine::runbook_execution::ExecutionStatus::Draft,
            "status after start must be Draft"
        );

        // 2. Approve
        let approved =
            ryuki_engine::runbook_execution::approve_execution_pure(&fetched, "change.manager")
                .expect("approve must succeed from Draft");
        let ok = crate::repos::runbook_executions::transition(pool, &id, &version, &approved)
            .await
            .expect("transition failed");
        assert!(ok, "approve transition must succeed");

        let (fetched, version) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found after approve");
        assert_eq!(
            fetched.status,
            ryuki_engine::runbook_execution::ExecutionStatus::Approved,
            "status after approve must be Approved"
        );

        // 3. Complete
        let completed = ryuki_engine::runbook_execution::complete_execution_pure(&fetched)
            .expect("complete must succeed from Approved");
        let ok = crate::repos::runbook_executions::transition(pool, &id, &version, &completed)
            .await
            .expect("transition failed");
        assert!(ok, "complete transition must succeed");

        let (fetched, _version) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found after complete");
        assert_eq!(
            fetched.status,
            ryuki_engine::runbook_execution::ExecutionStatus::Completed,
            "status after complete must be Completed"
        );

        cleanup(pool, &id).await;
    }

    /// Missing id must return None (mapped to 404 by handlers).
    #[tokio::test]
    async fn test_missing_id_404() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let missing_id = "rbx-defra-does-not-exist-00000000";

        let result = crate::repos::runbook_executions::get(pool, missing_id)
            .await
            .expect("get must not error on missing id");
        assert!(result.is_none(), "missing id must return None");
    }

    /// CAS: `transition` returns `Ok(false)` when DB status no longer matches
    /// the expected `before` value.
    #[tokio::test]
    async fn test_cas_conflict_returns_false() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let exec = make_exec(&suffix, "restart-service", "GBLON");
        let id = exec.id.clone();

        crate::repos::runbook_executions::insert(pool, &exec)
            .await
            .expect("insert must succeed");

        // Capture the execution + its row version while it is still Draft.
        let (draft, stale_version) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found");
        assert_eq!(
            draft.status,
            ryuki_engine::runbook_execution::ExecutionStatus::Draft
        );

        // Advance it to Approved through the normal path (this bumps the row version).
        let approved = ryuki_engine::runbook_execution::approve_execution_pure(&draft, "approver")
            .expect("approve must succeed");
        crate::repos::runbook_executions::transition(pool, &id, &stale_version, &approved)
            .await
            .expect("first transition must succeed");

        // A transition presenting the STALE row version must NOT apply, even
        // though it changes the status (the xmin token has advanced).
        let stale_update = ryuki_engine::runbook_execution::complete_execution_pure(&draft)
            .expect("complete_pure on draft must return Ok (not terminal)");
        let applied =
            crate::repos::runbook_executions::transition(pool, &id, &stale_version, &stale_update)
                .await
                .expect("transition query must not error");

        cleanup(pool, &id).await;
        assert!(
            !applied,
            "transition with a stale row version must return false (CAS mismatch)"
        );
    }

    /// Invalid state transition: attempting to approve a terminal execution --
    /// pure fn returns Err -> handler returns 409.
    #[tokio::test]
    async fn test_invalid_transition_409() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let exec = make_exec(&suffix, "patch-windows-server", "DEBER");
        let id = exec.id.clone();

        crate::repos::runbook_executions::insert(pool, &exec)
            .await
            .expect("insert must succeed");

        // Force the status to Completed via direct repo transition.
        let (_loaded, version) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found");
        let mut terminal = exec.clone();
        terminal.status = ryuki_engine::runbook_execution::ExecutionStatus::Completed;
        crate::repos::runbook_executions::transition(pool, &id, &version, &terminal)
            .await
            .expect("force-complete transition must succeed");

        let (fetched, _version) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found");

        // Attempting to approve a Completed execution must be rejected by the pure fn.
        let err = ryuki_engine::runbook_execution::approve_execution_pure(&fetched, "approver");
        cleanup(pool, &id).await;
        assert!(
            err.is_err(),
            "approve_execution_pure on a terminal execution must return Err (-> 409)"
        );
    }

    /// Same-status concurrency: two readers load the SAME running execution, both
    /// run a step (which keeps status = Running). The first write wins; the second
    /// presents a now-stale row version and MUST be rejected (Ok(false) -> 409),
    /// instead of silently clobbering the first writer's step result. This is the
    /// race a status-only CAS would miss (status stays "running" throughout).
    #[tokio::test]
    async fn test_same_status_step_race_returns_false() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let exec = make_exec(&suffix, "patch-windows-server", "DEFRA");
        let id = exec.id.clone();
        crate::repos::runbook_executions::insert(pool, &exec)
            .await
            .expect("insert must succeed");

        // Drive it to Running via a first step (Draft -> Running).
        let (loaded, v0) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get")
            .expect("found");
        let running = ryuki_engine::runbook_execution::execute_step_pure(&loaded, 1)
            .expect("step 1 must succeed");
        assert!(
            crate::repos::runbook_executions::transition(pool, &id, &v0, &running)
                .await
                .expect("transition")
        );

        // Two concurrent readers both observe the SAME running version.
        let (reader_a, ver_running) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get a")
            .expect("found a");
        let (reader_b, ver_running_b) = crate::repos::runbook_executions::get(pool, &id)
            .await
            .expect("get b")
            .expect("found b");
        assert_eq!(
            ver_running, ver_running_b,
            "both readers see the same version"
        );
        assert_eq!(
            reader_a.status,
            ryuki_engine::runbook_execution::ExecutionStatus::Running
        );

        // Reader A completes step 2 (status stays Running) — first write wins.
        let a_update =
            ryuki_engine::runbook_execution::execute_step_pure(&reader_a, 2).expect("a step 2");
        // Guard the test's own premise: both writes must keep status Running, else
        // a future fixture change could silently turn this into a status-CHANGING
        // case (which even the old status-only CAS would have caught).
        assert_eq!(
            a_update.status,
            ryuki_engine::runbook_execution::ExecutionStatus::Running,
            "A's step write must keep status Running (same-status race premise)"
        );
        assert!(
            crate::repos::runbook_executions::transition(pool, &id, &ver_running, &a_update)
                .await
                .expect("a transition"),
            "first same-status write must succeed"
        );

        // Reader B completes step 3 against the now-stale version — MUST be rejected,
        // even though status is still Running (this is the bug a status-only CAS missed).
        let b_update =
            ryuki_engine::runbook_execution::execute_step_pure(&reader_b, 3).expect("b step 3");
        assert_eq!(
            b_update.status,
            ryuki_engine::runbook_execution::ExecutionStatus::Running,
            "B's step write must keep status Running (same-status race premise)"
        );
        let applied =
            crate::repos::runbook_executions::transition(pool, &id, &ver_running_b, &b_update)
                .await
                .expect("b transition query must not error");

        cleanup(pool, &id).await;
        assert!(
            !applied,
            "second same-status writer with a stale version must return false (lost-update prevented)"
        );
    }

    /// list_by_site: insert two executions for the same site, list by site,
    /// assert both are returned and all belong to that site.
    #[tokio::test]
    async fn test_list_by_site() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let exec1 = make_exec(&format!("{suffix}-a"), "restart-service", "DEFRA");
        let exec2 = make_exec(&format!("{suffix}-b"), "certificate-renewal", "DEFRA");
        let id1 = exec1.id.clone();
        let id2 = exec2.id.clone();

        crate::repos::runbook_executions::insert(pool, &exec1)
            .await
            .expect("insert exec1 must succeed");
        crate::repos::runbook_executions::insert(pool, &exec2)
            .await
            .expect("insert exec2 must succeed");

        let listed = crate::repos::runbook_executions::list(pool, "DEFRA")
            .await
            .expect("list must succeed");

        cleanup(pool, &id1).await;
        cleanup(pool, &id2).await;

        assert!(
            listed.iter().any(|e| e.id == id1),
            "exec1 must appear in DEFRA list"
        );
        assert!(
            listed.iter().any(|e| e.id == id2),
            "exec2 must appear in DEFRA list"
        );
        assert!(
            listed.iter().all(|e| e.site == "DEFRA"),
            "all listed executions must be for DEFRA"
        );
    }
}

// Run with: RYUKI_DATABASE_URL=<url> cargo test -p ryuki-api --bins incident_contexts_db_tests -- --test-threads=1
#[cfg(test)]
mod incident_contexts_db_tests {
    use crate::database::DB_TEST_SERIAL;
    use sqlx::PgPool;

    async fn global_pool() -> Option<&'static PgPool> {
        let url = std::env::var("RYUKI_DATABASE_URL").ok()?;
        if url.is_empty() {
            return None;
        }
        crate::database::try_connect_with_url(&url, 5, 1, 300, 30, 1800).await;
        let pool = crate::database::get_db()?;
        crate::database::run_migrations(pool).await.ok()?;
        Some(pool)
    }

    async fn cleanup(pool: &PgPool, id: &str) {
        sqlx::query("DELETE FROM incident_contexts WHERE incident_id = $1")
            .bind(id)
            .execute(pool)
            .await
            .ok();
    }

    fn make_incident(suffix: &str, site: &str) -> ryuki_engine::incident_context::IncidentContext {
        ryuki_engine::incident_context::build_incident_context(
            &format!("test incident {suffix}"),
            "sev2",
            vec![format!("{}-test-ci", site.to_lowercase())],
            site,
        )
        .expect("build_incident_context must succeed")
    }

    /// Full lifecycle: assemble -> add-ci -> escalate -> resolve.
    /// Asserts status after each step: add-ci and escalate keep "active", resolve sets "resolved".
    #[tokio::test]
    async fn test_full_lifecycle() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let ctx = make_incident(&suffix, "DEFRA");
        let id = ctx.incident_id.clone();

        // 1. Insert (assemble)
        crate::repos::incident_contexts::insert(pool, &ctx)
            .await
            .expect("insert must succeed");

        let (fetched, version) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found after insert");
        assert_eq!(
            fetched.status, "active",
            "status after insert must be active"
        );
        let initial_ci_count = fetched.affected_ci.len();

        // 2. Add CI (status stays "active")
        let with_ci = ryuki_engine::incident_context::add_affected_ci_pure(
            &fetched,
            "defra-extra-host",
            "server",
        )
        .expect("add_affected_ci_pure must succeed");
        assert_eq!(with_ci.status, "active", "add_ci must keep status active");
        assert_eq!(
            with_ci.affected_ci.len(),
            initial_ci_count + 1,
            "affected_ci must grow by 1"
        );

        let ok = crate::repos::incident_contexts::transition(pool, &id, &version, &with_ci)
            .await
            .expect("transition failed");
        assert!(ok, "add_ci transition must succeed");

        let (fetched, version) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found after add_ci");
        assert_eq!(fetched.status, "active");
        assert_eq!(
            fetched.affected_ci.len(),
            initial_ci_count + 1,
            "re-get must persist the grown affected_ci"
        );

        // 3. Escalate (status stays "active")
        let escalated =
            ryuki_engine::incident_context::escalate_pure(&fetched, "customer impact exceeded")
                .expect("escalate_pure must succeed");
        assert_eq!(
            escalated.status, "active",
            "escalate must keep status active"
        );
        assert!(
            escalated
                .on_call
                .escalation
                .contains("customer impact exceeded"),
            "escalation field must contain the reason"
        );

        let ok = crate::repos::incident_contexts::transition(pool, &id, &version, &escalated)
            .await
            .expect("transition failed");
        assert!(ok, "escalate transition must succeed");

        let (fetched, version) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found after escalate");
        assert_eq!(fetched.status, "active");
        assert!(
            fetched
                .on_call
                .escalation
                .contains("customer impact exceeded"),
            "re-get must persist the escalation reason"
        );

        // 4. Resolve (status changes to "resolved")
        let resolved =
            ryuki_engine::incident_context::resolve_incident_pure(&fetched, "service restored")
                .expect("resolve_incident_pure must succeed");
        assert_eq!(
            resolved.status, "resolved",
            "resolve must set status to resolved"
        );

        let ok = crate::repos::incident_contexts::transition(pool, &id, &version, &resolved)
            .await
            .expect("transition failed");
        assert!(ok, "resolve transition must succeed");

        let (fetched, _version) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found after resolve");
        assert_eq!(
            fetched.status, "resolved",
            "status after resolve must persist"
        );
        assert_eq!(
            fetched.resolution,
            Some("service restored".to_string()),
            "resolution text must persist"
        );

        cleanup(pool, &id).await;
    }

    /// Missing id must return None (mapped to 404 by handlers).
    #[tokio::test]
    async fn test_missing_id_404() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let result = crate::repos::incident_contexts::get(pool, "inc-does-not-exist-00000000")
            .await
            .expect("get must not error on missing id");
        assert!(result.is_none(), "missing id must return None");
    }

    /// CAS: transition returns Ok(false) when the row was modified after the read.
    #[tokio::test]
    async fn test_cas_conflict_returns_false() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let ctx = make_incident(&suffix, "GBLON");
        let id = ctx.incident_id.clone();

        crate::repos::incident_contexts::insert(pool, &ctx)
            .await
            .expect("insert must succeed");

        let (original, stale_version) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get failed")
            .expect("not found");

        // First writer escalates — this bumps xmin.
        let escalated =
            ryuki_engine::incident_context::escalate_pure(&original, "escalation reason a")
                .expect("escalate must succeed");
        crate::repos::incident_contexts::transition(pool, &id, &stale_version, &escalated)
            .await
            .expect("first transition must succeed");

        // Second writer presents stale version — must be rejected.
        let stale_update =
            ryuki_engine::incident_context::escalate_pure(&original, "escalation reason b")
                .expect("second escalate must succeed");
        let applied =
            crate::repos::incident_contexts::transition(pool, &id, &stale_version, &stale_update)
                .await
                .expect("transition query must not error");

        cleanup(pool, &id).await;
        assert!(
            !applied,
            "transition with stale row version must return false (CAS mismatch)"
        );
    }

    /// Resolve twice: second resolve with fresh version after re-get SUCCEEDS.
    /// Proves there is no guard on already-resolved (engine behavior: just overwrites).
    #[tokio::test]
    async fn test_resolve_twice_overwrites() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let ctx = make_incident(&suffix, "DEFRA");
        let id = ctx.incident_id.clone();

        crate::repos::incident_contexts::insert(pool, &ctx)
            .await
            .expect("insert must succeed");

        // First resolve
        let (loaded, v1) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get")
            .expect("found");
        let resolved1 = ryuki_engine::incident_context::resolve_incident_pure(&loaded, "first fix")
            .expect("resolve 1");
        let ok = crate::repos::incident_contexts::transition(pool, &id, &v1, &resolved1)
            .await
            .expect("transition 1");
        assert!(ok, "first resolve must succeed");

        // Re-get to get fresh version, then resolve again
        let (already_resolved, v2) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get 2")
            .expect("found 2");
        assert_eq!(already_resolved.status, "resolved");

        let resolved2 =
            ryuki_engine::incident_context::resolve_incident_pure(&already_resolved, "second fix")
                .expect("resolve 2 — no guard on already-resolved");
        let ok2 = crate::repos::incident_contexts::transition(pool, &id, &v2, &resolved2)
            .await
            .expect("transition 2");
        assert!(
            ok2,
            "second resolve with fresh version must succeed (no already-resolved guard)"
        );

        let (final_ctx, _) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("final get")
            .expect("found final");
        assert_eq!(final_ctx.resolution, Some("second fix".to_string()));

        cleanup(pool, &id).await;
    }

    /// Same-status add-ci race: two concurrent readers both run add_affected_ci_pure
    /// (status stays "active"). First write wins; second with stale version returns Ok(false).
    /// A status-only CAS would miss this because status is "active" in both writes.
    #[tokio::test]
    async fn test_same_status_add_ci_race_returns_false() {
        let _serial = DB_TEST_SERIAL.lock().await;
        let Some(pool) = global_pool().await else {
            eprintln!("SKIP: RYUKI_DATABASE_URL not set / DB unavailable");
            return;
        };

        let suffix = uuid::Uuid::new_v4().to_string();
        let ctx = make_incident(&suffix, "GBLON");
        let id = ctx.incident_id.clone();

        crate::repos::incident_contexts::insert(pool, &ctx)
            .await
            .expect("insert must succeed");

        // Two readers load the SAME active incident simultaneously.
        let (reader_a, ver_a) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get a")
            .expect("found a");
        let (reader_b, ver_b) = crate::repos::incident_contexts::get(pool, &id)
            .await
            .expect("get b")
            .expect("found b");
        assert_eq!(ver_a, ver_b, "both readers must see the same xmin version");
        assert_eq!(reader_a.status, "active");

        // Reader A adds CI — status stays "active" (this is the same-status race premise).
        let a_update = ryuki_engine::incident_context::add_affected_ci_pure(
            &reader_a,
            "gblon-extra-a",
            "server",
        )
        .expect("add_ci a");
        assert_eq!(
            a_update.status, "active",
            "add_ci must keep status active (same-status race premise)"
        );
        let ok_a = crate::repos::incident_contexts::transition(pool, &id, &ver_a, &a_update)
            .await
            .expect("a transition");
        assert!(ok_a, "first same-status write must succeed");

        // Reader B adds a different CI with the now-stale version — must be rejected.
        let b_update = ryuki_engine::incident_context::add_affected_ci_pure(
            &reader_b,
            "gblon-extra-b",
            "server",
        )
        .expect("add_ci b");
        assert_eq!(
            b_update.status, "active",
            "B's add_ci must also keep status active (same-status race premise)"
        );
        let ok_b = crate::repos::incident_contexts::transition(pool, &id, &ver_b, &b_update)
            .await
            .expect("b transition query must not error");

        cleanup(pool, &id).await;
        assert!(
            !ok_b,
            "second same-status writer with stale version must return false (xmin CAS catches it; status-only CAS would miss it)"
        );
    }
}
